[183] = {183, "backrub_ui_tips1", "沿著規定好的路線，為駕駛員打上肥皂吧！\n正確的路線，能最大效率的利用肥皂~", "0", "0", "0"},
[184] = {184, "backrub_ui_tips2", "完成時間越短，評分越高", "0", "0", "0"},
[185] = {185, "backrub_ui_tips3", "因在海洋作戰，偶爾會有棲息於此的生物掛在駕駛員身上，\n看準時機點擊螢幕按鈕，幫助駕駛員趕走身上的動物吧！", "0", "0", "0"},
[186] = {186, "backrub_ui_tips4", "為駕駛員挑選最合適的護膚品吧，不同地區的駕駛員適用的護膚品也不同，\n仔細看好每個問題，才能選出最適合駕駛員的那一款~", "0", "0", "0"},
[187] = {187, "backrub_ui_tips5", "答對的題目越多，選擇的護膚品就越合適，\n可不要選錯護膚品哦，不同的護膚品，保養的功效也不同~", "0", "0", "0"},
[188] = {188, "backrub_ui_tips6", "小於等於 <color=#32ffed>%s</color> 秒", "0", "0", "0"},
[189] = {189, "backrub_ui_shower_second", "</color> 秒", "0", "0", "0"},
