[1864] = {1864, "ui_qita_text172", "參與超越調度的領航，將會根據領航在當期卡池抽取的次數獲得一定量的能源晶體獎勵（獎勵將會通過郵件發放）：\n累積抽取滿20次，可獲得能源晶體*2000\n累積抽取滿40次，可獲得能源晶體*2000\n累積抽取滿60次，可獲得能源晶體*2000\n累積抽取滿80次，可獲得能源晶體*2000\n累積抽取滿100次，可獲得能源晶體*2000\n累積抽取滿150次，可獲得能源晶體*3000\n累積抽取滿200次，可獲得能源晶體*3000\n累積抽取滿250次，可獲得能源晶體*3000\n累積抽取滿300次，可獲得能源晶體*3000\n累積抽取滿350次，可獲得能源晶體*4000\n累積抽取滿400次，可獲得能源晶體*4000\n累積抽取滿450次，可獲得能源晶體*4000\n累積抽取滿500次，可獲得能源晶體*6000\n\n若領航因故未受到郵件，請聯繫客服群回饋。", "0", "0", "0"},
