[2610] = {2610, "ui_return_text1", "別緒萬千", "0", "0", "0"},
[2611] = {2611, "ui_return_text2", "終於聯繫上了……！！\n哥哥你現在還好嗎？沒有受傷吧？這段時間有好好吃飯嗎？吉雅知道，這次秘密行動是媽媽安排的，並且要求哥哥嚴格保密，不可以告訴任何人。所以吉雅不會多問，更不會追問，請哥哥放心啦。但如果有下次——吉雅是說如果！只是一個假設哦！\n如果以後媽媽又讓哥哥做相類似的事情，可不可以在離開之前，和吉雅說一聲？不要再突然消失不見了……%s天，一共有%s天呢。吉雅聯繫不上哥哥，一個人在多瑙，真的很害怕……啊，對了。在哥哥失聯的這段時間裡，各地的駕駛員們也都對哥哥的去向非常關心，時常來電詢問你的近況。需要吉雅將您即將返回多瑙支部的消息同步給她們嗎？還是說，哥哥更想自己親口告訴她們？", "0", "0", "0"},
[2612] = {2612, "ui_return_text3", "吉雅準備的物資，應該都是哥哥用得上的~", "0", "0", "0"},
[2613] = {2613, "ui_return_text4", "家人的愛", "0", "0", "0"},
[2614] = {2614, "ui_dmm_login1", "データ連携", "0", "0", "0"},
[2615] = {2615, "ui_dmm_login2", "すでにハツリバーブ-HAZEREVERB-をプレイしている場合は\n<color=#ED6A47>データ連携</color>を選択してください\n以前のゲームデータと連携してプレイすることができます\n<color=#ED6A47>異なるOS</color>にデータ連携した場合、<color=#ED6A47>連携前のOS</color>で所持していた\n<color=#ED6A47>原初結晶は連携後のOSでは使用できません</color>\n連携前のOSに戻ると使用できるようになります", "0", "0", "0"},
[2616] = {2616, "ui_dmm_login3", "いいえ", "0", "0", "0"},
[2617] = {2617, "ui_dmm_login4", "ゲームデータ情報", "0", "0", "0"},
[2618] = {2618, "ui_dmm_login5", "このゲームデータと連携しますか？", "0", "0", "0"},
[2619] = {2619, "ui_dmm_login6", "データ連携確認", "0", "0", "0"},
[2620] = {2620, "ui_dmm_login7", "現在プレイされている以下のデータは\n上書きされ復元できなくなります", "0", "0", "0"},
[2621] = {2621, "ui_dmm_login8", "本当によろしいですか？", "0", "0", "0"},
[2622] = {2622, "ui_dmm_login9", "他プラットフォームと連携を行う場合は\n所持している原初結晶は連携できません", "0", "0", "0"},
[2623] = {2623, "ui_dmm_login10", "データ連携を行う事で\n複数の端末でハツリバーブ-HAZEREVERB-の\nゲームデータを共有してプレイ出来ます\nデータ連携には<color=#ED6A47>引き続きID</color>と<color=#ED6A47>連携パスワード</color>が必要です。\n<color=#ED6A47>異なるOS</color>にデータ連携した場合、<color=#ED6A47>連携前のOS</color>で所持していた\n<color=#ED6A47>原初結晶は連携後のOSでは使用できません</color>\n連携前のOSに戻ると使用できるようになります", "0", "0", "0"},
